title:
$relativeFiles = @(git ls-files --modified --others --exclude-standard | Where-Object {
  $_ -ne 'gold-band' -and $_ -notlike 'gold-band/*' -and
  $_ -ne 'original-pi' -and $_ -notlike 'original-pi/*' -and
  $_ -notlike '.gold-band/*'
})
$fileMap = @{}
foreach ($relative in $relativeFiles) {
  $absolute = Join-Path (Get-Location) $relative
  if (Test-Path -LiteralPath $absolute -PathType Leaf) {
    $fileMap[$relative] = $absolute
  }
}
$conflictFiles = [System.Collections.Generic.List[string]]::new()
$privateKeyFiles = [System.Collections.Generic.List[string]]::new()
$absolutePathFiles = [System.Collections.Generic.List[string]]::new()
$contents = @{}
foreach ($entry in $fileMap.GetEnumerator()) {
  try {
    $text = [System.IO.File]::ReadAllText($entry.Value)
    $contents[$entry.Key] = $text
    if ($text -match '(?m)^(<<<<<<< |=======\s*$|>>>>>>> )') { $conflictFiles.Add($entry.Key) }
    if ($text -match '-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----') { $privateKeyFiles.Add($entry.Key) }
    if ($text -match '(?i)(?:/export/user\\|E:\\Projects\\Code\\AI\\Ji|\.gold-band\\worktrees\\task-015|dyn-[0-9a-f]{8,})') { $absolutePathFiles.Add($entry.Key) }
  } catch {}
}
$envSecrets = [System.Collections.Generic.List[string]]::new()
if (Test-Path -LiteralPath '.env') {
  foreach ($line in Get-Content -LiteralPath '.env') {
    if ($line -match '^\s*(?:export\s+)?[A-Za-z_][A-Za-z0-9_]*\s*=\s*(.+?)\s*$') {
      $value = $matches[1].Trim()
      if (($value.StartsWith('"') -and $value.EndsWith('"')) -or ($value.StartsWith("'") -and $value.EndsWith("'"))) {
        $value = $value.Substring(1, $value.Length - 2)
      }
      if ($value.Length -ge 8 -and $value -notmatch '^(?:changeme|example|placeholder|your[-_])') {
        foreach ($entry in $contents.GetEnumerator()) {
          if ($entry.Value.Contains($value) -and -not $envSecrets.Contains($entry.Key)) {
            $envSecrets.Add($entry.Key)
          }
        }
      }
    }
  }
}
"SCANNED_FILE_COUNT=$($fileMap.Count)"
"CONFLICT_MARKER_FILE_COUNT=$($conflictFiles.Count)"
if ($conflictFiles.Count -gt 0) { $conflictFiles | Sort-Object }
"PRIVATE_KEY_FILE_COUNT=$($privateKeyFiles.Count)"
if ($privateKeyFiles.Count -gt 0) { $privateKeyFiles | Sort-Object }
"EXACT_ENV_SECRET_MATCH_FILE_COUNT=$($envSecrets.Count)"
if ($envSecrets.Count -gt 0) { $envSecrets | Sort-Object }
"LOCAL_PATH_MATCH_FILE_COUNT=$($absolutePathFiles.Count)"
if ($absolutePathFiles.Count -gt 0) { $absolutePathFiles | Sort-Object }

$rootPattern = [regex]::Escape((Get-Location).Path)
$matches = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
  $_.ProcessId -ne $PID -and $_.Name -match '^(java|javaw|node|pwsh|powershell|cmd)\.exe$' -and $_.CommandLine -match $rootPattern
})
"JI_WORKSPACE_PROCESS_COUNT=$($matches.Count)"
$matches | ForEach-Object { "PID=$($_.ProcessId) NAME=$($_.Name)" }
$tempMatches = @(Get-ChildItem -LiteralPath $env:TEMP -Directory -ErrorAction SilentlyContinue | Where-Object {
  $_.Name -match '^ji-(?:api-baseline|consumer|stage|workspace|artifact|session)'
})
"JI_TEMP_DIRECTORY_COUNT=$($tempMatches.Count)"
$tempMatches | Sort-Object Name | ForEach-Object { "TEMP=$($_.Name)" }

$secretEntries = @()
if (Test-Path -LiteralPath '.env') {
  foreach ($line in Get-Content -LiteralPath '.env') {
    if ($line -match '^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+?)\s*$') {
      $name = $matches[1]
      $value = $matches[2].Trim()
      if (($value.StartsWith('"') -and $value.EndsWith('"')) -or ($value.StartsWith("'") -and $value.EndsWith("'"))) {
        $value = $value.Substring(1, $value.Length - 2)
      }
      if ($name -match '(?i)(?:KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL|PRIVATE)' -and $value.Length -ge 8) {
        $secretEntries += [pscustomobject]@{ Name = $name; Value = $value }
      }
    }
  }
}
$currentFile = $null
$exactHits = [System.Collections.Generic.HashSet[string]]::new()
$keyShapeFiles = [System.Collections.Generic.HashSet[string]]::new()
$privateKeyFiles = [System.Collections.Generic.HashSet[string]]::new()
$localPathFiles = [System.Collections.Generic.HashSet[string]]::new()
$conflictFiles = [System.Collections.Generic.HashSet[string]]::new()
$addedLineCount = 0
$diff = @(git diff --cached --no-color --unified=0 -- . ':(exclude)gold-band' ':(exclude)original-pi')
foreach ($line in $diff) {
  if ($line.StartsWith('+++ b/')) {
    $currentFile = $line.Substring(6)
    continue
  }
  if ($null -eq $currentFile -or -not $line.StartsWith('+') -or $line.StartsWith('+++')) { continue }
  $addedLineCount++
  $added = $line.Substring(1)
  if ($added -match '^(?:<<<<<<< |=======\s*$|>>>>>>> )') { [void]$conflictFiles.Add($currentFile) }
  if ($added -match '-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----') { [void]$privateKeyFiles.Add($currentFile) }
  if ($added -match '(?i)(?:sk-[A-Za-z0-9_-]{20,}|gh[pousr]_[A-Za-z0-9]{20,}|AIza[A-Za-z0-9_-]{20,})') { [void]$keyShapeFiles.Add($currentFile) }
  if ($added -match '(?i)(?:/export/user\\|E:\\Projects\\Code\\AI\\Ji|\.gold-band\\worktrees\\task-015|dyn-[0-9a-f]{8,})') { [void]$localPathFiles.Add($currentFile) }
  foreach ($secret in $secretEntries) {
    if ($added.Contains($secret.Value)) { [void]$exactHits.Add("$($secret.Name) $currentFile") }
  }
}
"STAGED_ADDED_LINE_COUNT=$addedLineCount"
"EXACT_SENSITIVE_ENV_MATCH_COUNT=$($exactHits.Count)"
$exactHits | Sort-Object
"KNOWN_KEY_SHAPE_FILE_COUNT=$($keyShapeFiles.Count)"
$keyShapeFiles | Sort-Object
"PRIVATE_KEY_FILE_COUNT=$($privateKeyFiles.Count)"
$privateKeyFiles | Sort-Object
"LOCAL_RUNTIME_PATH_FILE_COUNT=$($localPathFiles.Count)"
$localPathFiles | Sort-Object
"CONFLICT_MARKER_FILE_COUNT=$($conflictFiles.Count)"
$conflictFiles | Sort-Object
